preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;600;700&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 1rem .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtfan-font-size로 바꿉니다. */
.rtfan {
  --rtfan-bg-fill: transparent;
  --rtfan-bg-border: 0;
  --rtfan-blur: none;
  --rtfan-bg-edge: none;
  --rtfan-bg-sheen: linear-gradient(transparent, transparent);
  --rtfan-bg-fallback: transparent;
  --rtfan-font-body: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtfan-font-display: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtfan-font-size: 16px;
  --rtfan-line-height: 1.85;
  --rtfan-para-gap: .9em;
  --rtfan-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtfan {
  --risu-font-family: var(--rtfan-font-body);
  --FontColorStandard: var(--rtfan-ink);
  --FontColorBold: var(--rtfan-strong, var(--rtfan-ink));
  --FontColorItalic: var(--rtfan-muted);
  --FontColorItalicBold: var(--rtfan-muted);
  --FontColorQuote1: var(--rtfan-muted);
  --FontColorQuote2: var(--rtfan-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtfan-ink);
  font-family: var(--rtfan-font-body);
  font-size: var(--rtfan-font-size);
  line-height: var(--rtfan-line-height);
  letter-spacing: var(--rtfan-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtfan, .rtfan *, .rtfan *::before, .rtfan *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtfan.rtfan { display: block; }
.rtfan ::selection { background: color-mix(in srgb, var(--rtfan-accent) 26%, transparent); color: inherit; }
.rtfan__content {
  min-width: 0;
  color: var(--rtfan-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtfan__content .chattext {
  --tw-prose-code: var(--rtfan-strong, var(--rtfan-ink));
  --tw-prose-pre-code: var(--rtfan-ink);
  --tw-prose-pre-bg: var(--rtfan-tint);
  max-width: none;
  color: var(--rtfan-ink);
  font-size: var(--rtfan-font-size) !important;
  line-height: var(--rtfan-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtfan__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtfan-font-size);
  line-height: var(--rtfan-line-height);
}
.rtfan__content :where(p) { margin: 0 0 var(--rtfan-para-gap); }
.rtfan__content :where(p:last-child) { margin-bottom: 0; }
.rtfan__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtfan-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtfan-strong, var(--rtfan-ink));
  font-family: var(--rtfan-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtfan__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtfan__content :where(h1) { font-size: calc(var(--rtfan-font-size) * 1.55); }
.rtfan__content :where(h2) { font-size: calc(var(--rtfan-font-size) * 1.32); }
.rtfan__content :where(h3) { font-size: calc(var(--rtfan-font-size) * 1.15); }
.rtfan__content :where(h4, h5, h6) { font-size: var(--rtfan-font-size); color: var(--rtfan-muted); }
.rtfan__content :where(strong) { font-weight: 700; color: var(--rtfan-strong, var(--rtfan-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtfan__content :where(em) { font-style: normal; color: var(--rtfan-muted); }
.rtfan__content mark[risu-mark="quote1"],
.rtfan__content mark[risu-mark="blockquote1"] { color: var(--rtfan-muted); background: transparent; }
.rtfan__content mark[risu-mark="quote2"],
.rtfan__content mark[risu-mark="blockquote2"] {
  color: var(--rtfan-dialog);
  font-weight: var(--rtfan-dialog-weight);
  background: transparent;
}
.rtfan__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtfan-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtfan-tint);
  color: var(--rtfan-muted);
}
.rtfan__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtfan__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtfan-ink); }
.rtfan__content :where(li)::marker { color: var(--rtfan-accent); }
.rtfan__content :where(a) {
  color: var(--rtfan-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtfan-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtfan__content :where(a:hover) { text-decoration-color: currentColor; }
.rtfan__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtfan-line) 15%, var(--rtfan-line) 85%, transparent);
}
.rtfan__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtfan-strong, var(--rtfan-ink));
  background: var(--rtfan-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtfan-font-size) * .88);
  line-height: 1.5;
}
.rtfan__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtfan-ink);
  background: var(--rtfan-tint);
  border: 1px solid var(--rtfan-line);
  border-radius: .5rem;
  font-size: calc(var(--rtfan-font-size) * .88);
  line-height: 1.55;
}
.rtfan__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtfan__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtfan__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtfan-ink);
  border-bottom: 1px solid var(--rtfan-line);
  text-align: left;
  vertical-align: top;
}
.rtfan__content :where(th) {
  background: var(--rtfan-tint);
  color: var(--rtfan-strong, var(--rtfan-ink));
  font-weight: 600;
}
.rtfan__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtfan__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtfan-ink) !important;
  background: var(--rtfan-edit-bg) !important;
  border: 1px solid var(--rtfan-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtfan-font-size) !important;
  line-height: var(--rtfan-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtfan__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtfan-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtfan-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtfan__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtfan-muted);
  --color-textcolor2: var(--rtfan-muted);
  --color-textcolor: var(--rtfan-ink);
  --color-darkborderc: var(--rtfan-line);
  --color-darkbutton: var(--rtfan-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtfan-muted);
}
.rtfan__info, .rtfan__actions { min-width: 0; max-width: 100%; }
.rtfan__info > div, .rtfan__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtfan-muted); }
.rtfan__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtfan__info button.transition-all,
.rtfan__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtfan__info button.transition-all:hover,
.rtfan__actions button[class*="button-icon-"]:hover { background: var(--rtfan-tint); color: var(--rtfan-ink); }
.rtfan__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtfan-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtfan__info button:not(.transition-all):hover { background: var(--rtfan-tint); color: var(--rtfan-ink); }
.rtfan :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtfan-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtfan__portrait { overflow: hidden; background: var(--rtfan-tint); }
.rtfan__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtfan, .rtfan * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtfan .rtfan__bg {
    background: var(--rtfan-bg-fallback, var(--rtfan-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtfan .rtfan__bg { background: var(--rtfan-bg-fallback, var(--rtfan-bg-fill)); }
}

.rtfan__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtfan-bg-fill);
  border: var(--rtfan-bg-border, 0);
  -webkit-backdrop-filter: var(--rtfan-blur);
  backdrop-filter: var(--rtfan-blur);
  box-shadow: var(--rtfan-bg-edge);
}

/* 구조: 판타지 */

.rtfan {
  max-width: 50rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 4%, 2.4rem) clamp(1.4rem, 5%, 2.9rem) 1.3rem;
  border-radius: .45rem;
  border: 1px solid var(--rtfan-line);
  box-shadow: 0 12px 32px var(--rtfan-shadow);
}
/* 양피지 연대기 바탕: 얼룩, 모서리 음영, 이중 세선 테두리 */
.rtfan .rtfan__bg {
  background:
    var(--rtfan-bg-sheen),
    radial-gradient(ellipse at 10% 6%, var(--rtfan-stain) 0, transparent 44%),
    radial-gradient(ellipse at 92% 94%, var(--rtfan-stain) 0, transparent 42%),
    radial-gradient(ellipse at 50% 50%, transparent 56%, var(--rtfan-vignette, transparent) 100%),
    var(--rtfan-paper);
  box-shadow:
    var(--rtfan-bg-edge),
    inset 0 0 0 1px var(--rtfan-line),
    inset 0 0 0 5px transparent,
    inset 0 0 0 6px color-mix(in srgb, var(--rtfan-accent) 32%, transparent);
}
.rtfan::before, .rtfan::after {
  content: "✦";
  position: absolute;
  top: .62rem;
  color: var(--rtfan-accent);
  font-size: clamp(.72rem, 1.4vw, 1rem);
  line-height: 1;
  opacity: .78;
  pointer-events: none;
}
.rtfan::before { left: .72rem; }
.rtfan::after { right: .72rem; }
.rtfan__head {
  display: flex;
  align-items: center;
  gap: .95rem;
  margin-bottom: 1.05rem;
  padding-bottom: .75rem;
  border-bottom: 1px solid var(--rtfan-line);
}
/* 입체 밀랍 인장 */
.rtfan__portrait {
  flex: 0 0 auto;
  width: var(--rtfan-seal-w);
  aspect-ratio: 1;
  border-radius: 50%;
  border: clamp(2px, .5vw, 4px) solid var(--rtfan-seal);
  box-shadow:
    inset 0 2px 4px rgba(255, 255, 255, .25),
    0 0 0 clamp(2px, .45vw, 3.5px) var(--rtfan-seal-dark),
    0 5px 14px var(--rtfan-shadow);
}
.rtfan { --rtfan-seal-w: clamp(3.2rem, 9%, 4.8rem); }
.rtfan--user { --rtfan-seal-w: clamp(2.6rem, 7%, 3.7rem); }
.rtfan__title {
  font-family: var(--rtfan-font-display);
  font-size: 1.22em;
  font-weight: 700;
  color: var(--rtfan-strong, var(--rtfan-ink));
}
.rtfan__suffix { color: var(--rtfan-muted); font-weight: 400; font-size: .84em; }
.rtfan--char .rtfan__content .chattext > p:first-child::first-letter {
  float: left;
  margin: .05em .08em 0 0;
  padding: .04em .12em 0 0;
  color: var(--rtfan-accent);
  font-family: var(--rtfan-font-display);
  font-size: 2.55em;
  line-height: .88;
  font-weight: 700;
}
.rtfan__footer { margin-top: .95rem; padding-top: .55rem; border-top: 1px dashed var(--rtfan-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (숲) ── */
.rtfan {
  --rtfan-paper: #dddac1;
  --rtfan-stain: rgba(76, 94, 48, .15);
  --rtfan-vignette: rgba(54, 68, 36, .14);
  --rtfan-ink: #242e1d;
  --rtfan-strong: #141c0f;
  --rtfan-muted: #5c684f;
  --rtfan-accent: #786b32;
  --rtfan-dialog: #394c2c;
  --rtfan-seal: #4b5e35;
  --rtfan-seal-dark: #8a7a3c;
  --rtfan-shadow: rgba(26, 38, 18, .25);
  --rtfan-line: #b0af8b;
  --rtfan-tint: #d1ceb1;
  --rtfan-edit-bg: #ebe9d5;
}
